create type experiment_type as enum('main_image','title','price','detail_page','promotion','bundle','other');create type experiment_status as enum('active','completed','cancelled');
create table experiments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,sku_id uuid references skus(id) on delete set null,sku_code text not null,type experiment_type not null,hypothesis text not null,change_description text not null,start_date date not null,end_date date,before_metrics jsonb not null,after_metrics jsonb,result text,conclusion text,status experiment_status not null default'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_active_experiment_per_sku on experiments(user_id,sku_code) where status='active';create index experiments_user_created_idx on experiments(user_id,created_at desc);alter table experiments enable row level security;create policy "own experiments" on experiments for all using(user_id=auth.uid()) with check(user_id=auth.uid());
